INSERT INTO versiones_firmware (id,version,chip,tipo_dispositivo,descripcion,manifiesto,directorio,ubicacion_archivo,publicado,descontinuado,creado_por)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM versiones_firmware),'1.1.8','ESP32','riego',
'Seguridad sin conexion: la reconexion WiFi/MQTT ya no bloquea el loop (el tiempo maximo de la bomba y la proteccion sin agua se evaluan aunque se caiga el broker); los reportes de estado que fallan se reenvian en orden al reconectar (cola de 4); un ON repetido no prolonga el riego en curso; tras cerrar la valvula de relleno por tiempo maximo no se reabre sola hasta leer tanque lleno o un VALVULA_ON manual; reles en LOW antes de configurar los pines y watchdog de 30 s.',
'{"schema_version": 1, "version": "1.1.8", "chip": "ESP32", "tipo_dispositivo": "riego", "source_sha256": "7d678091a986601f88cac3c80cbb6aacec1f36343a1f76794d331a3efb8ed798", "segmentos": [{"nombre": "esp32.ino.bootloader.bin", "direccion": 4096, "tamano": 24992, "sha256": "427f96e10c620c4f062dab15da54fc45494d897e8397ae6f3aecc98c42d7e379"}, {"nombre": "esp32.ino.partitions.bin", "direccion": 32768, "tamano": 3072, "sha256": "148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1"}, {"nombre": "boot_app0.bin", "direccion": 57344, "tamano": 8192, "sha256": "f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0"}, {"nombre": "esp32.ino.bin", "direccion": 65536, "tamano": 1021824, "sha256": "99589bfe65bcb6fec89d439d72ea81084dbfea5bad9920394350c836c9242edc"}]}'::jsonb,'esp32-riego-1.1.8','firmware_store/esp32-riego-1.1.8',true,false,
(SELECT MIN(id) FROM usuarios WHERE id_rol=1)
WHERE EXISTS (SELECT 1 FROM usuarios WHERE id_rol=1) AND NOT EXISTS
(SELECT 1 FROM versiones_firmware WHERE version='1.1.8' AND chip='ESP32' AND tipo_dispositivo='riego');
UPDATE versiones_firmware SET
descripcion='Seguridad sin conexion: la reconexion WiFi/MQTT ya no bloquea el loop (el tiempo maximo de la bomba y la proteccion sin agua se evaluan aunque se caiga el broker); los reportes de estado que fallan se reenvian en orden al reconectar (cola de 4); un ON repetido no prolonga el riego en curso; tras cerrar la valvula de relleno por tiempo maximo no se reabre sola hasta leer tanque lleno o un VALVULA_ON manual; reles en LOW antes de configurar los pines y watchdog de 30 s.',
manifiesto='{"schema_version": 1, "version": "1.1.8", "chip": "ESP32", "tipo_dispositivo": "riego", "source_sha256": "7d678091a986601f88cac3c80cbb6aacec1f36343a1f76794d331a3efb8ed798", "segmentos": [{"nombre": "esp32.ino.bootloader.bin", "direccion": 4096, "tamano": 24992, "sha256": "427f96e10c620c4f062dab15da54fc45494d897e8397ae6f3aecc98c42d7e379"}, {"nombre": "esp32.ino.partitions.bin", "direccion": 32768, "tamano": 3072, "sha256": "148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1"}, {"nombre": "boot_app0.bin", "direccion": 57344, "tamano": 8192, "sha256": "f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0"}, {"nombre": "esp32.ino.bin", "direccion": 65536, "tamano": 1021824, "sha256": "99589bfe65bcb6fec89d439d72ea81084dbfea5bad9920394350c836c9242edc"}]}'::jsonb,
directorio='esp32-riego-1.1.8',ubicacion_archivo='firmware_store/esp32-riego-1.1.8',publicado=true,descontinuado=false,fecha_descontinuado=NULL
WHERE version='1.1.8' AND chip='ESP32' AND tipo_dispositivo='riego';
UPDATE versiones_firmware SET publicado=false,descontinuado=true,fecha_descontinuado=COALESCE(fecha_descontinuado,now())
WHERE chip='ESP32' AND tipo_dispositivo='riego' AND version<>'1.1.8';
SELECT setval(pg_get_serial_sequence('versiones_firmware','id'),(SELECT MAX(id) FROM versiones_firmware));
